mapper.update:
UPDATE post
SET content = #{content},
    file_url = #{fileUrl},
    subscriber_only = #{subscriberOnly}
WHERE id = #{id}

UPDATE post
SET like_count = like_count + 1
WHERE id = #{postId}

UPDATE post
SET like_count = GREATEST(like_count - 1, 0)
WHERE id = #{postId}

mapper.select:
SELECT EXISTS (
SELECT 1
FROM subscription
WHERE member_id = #{memberId} AND creator_id = #{creatorId}
AND status = 'ACTIVE' AND end_date > CURRENT_TIMESTAMP
)
